// 1. 聚合根示例：订单聚合
public class Order extends AggregateRoot<OrderId> {
    private OrderStatus status;
    private List<OrderLine> lines;
    private Money totalAmount;
    private CustomerId customerId;

    // 工厂方法 - 充血模型
    public static Order create(CustomerId customerId, List<OrderLine> lines) {
        Order order = new Order();
        order.id = OrderId.generate();
        order.customerId = customerId;
        order.lines = new ArrayList<>(lines);
        order.status = OrderStatus.CREATED;
        order.totalAmount = lines.stream()
            .map(OrderLine::getSubtotal)
            .reduce(Money.ZERO, Money::add);
        // 发布领域事件
        order.registerEvent(new OrderCreatedEvent(order.id, order.totalAmount));
        return order;
    }

    // 业务方法 - 状态转换封装在聚合内部
    public void confirm(PaymentId paymentId) {
        if (this.status != OrderStatus.CREATED) {
            throw new DomainException("只有待确认订单才能确认");
        }
        this.status = OrderStatus.CONFIRMED;
        this.registerEvent(new OrderConfirmedEvent(this.id, paymentId));
    }
}

// 2. 值对象示例
public class Money {
    private final BigDecimal amount;
    private final String currency;

    public Money(BigDecimal amount, String currency) {
        this.amount = Objects.requireNonNull(amount);
        this.currency = Objects.requireNonNull(currency);
    }

    public Money add(Money other) {
        if (!this.currency.equals(other.currency)) {
            throw new DomainException("币种不同不能相加");
        }
        return new Money(this.amount.add(other.amount), this.currency);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Money)) return false;
        Money money = (Money) o;
        return amount.compareTo(money.amount) == 0
            && currency.equals(money.currency);
    }
}

// 3. 防腐层示例
public class ExternalPaymentAdapter {
    private final AlipayClient alipayClient;

    // 将外部模型转换为领域模型
    public PaymentResult adapt(AlipayNotify notify) {
        return new PaymentResult(
            new PaymentId(notify.getTradeNo()),
            Money.of(notify.getTotalAmount(), "CNY"),
            notify.isSuccess() ? PaymentStatus.SUCCESS : PaymentStatus.FAILED
        );
    }
}
